//! Basic parts generated from the cuprite_wire basic library (`libs/`, MIT licensed).
//!
//! They need no KiCad installation to build. To import their netlists into pcbnew, add the
//! footprint library `libs/footprints/cuprite_basic.pretty` as `cuprite_basic` to the
//! footprint library table. The library is generated by `tools/generate_basic_library.py`.

use crate::kicad_part;

kicad_part! {
    /// A resistor in an 0603 (1608 metric) chip: `Resistor0603::new("10k")`.
    pub struct Resistor0603 {
        symbol: "cuprite_basic:R",
        value: param,
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

kicad_part! {
    /// A capacitor in an 0603 (1608 metric) chip: `Capacitor0603::new("100n")`.
    pub struct Capacitor0603 {
        symbol: "cuprite_basic:C",
        value: param,
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

kicad_part! {
    /// An inductor in an 0603 (1608 metric) chip: `Inductor0603::new("10u")`.
    pub struct Inductor0603 {
        symbol: "cuprite_basic:L",
        value: param,
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

kicad_part! {
    /// A small-signal diode in SOD-123 with a generic model; the value is the part number.
    /// Pins: `K` (cathode) and `A` (anode).
    pub struct DiodeSod123 {
        symbol: "cuprite_basic:D",
        value: param,
        pins: { "1" => "k", "2" => "a" },
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

kicad_part! {
    /// An LED in an 0603 chip with a generic red LED model; the value is the part number.
    pub struct Led0603 {
        symbol: "cuprite_basic:LED",
        value: param,
        pins: { "1" => "k", "2" => "a" },
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

kicad_part! {
    /// A single op-amp in SOT-23-5 with a single-pole model (gain 100k, gain-bandwidth 1 MHz,
    /// no supply rails); the value is the part number.
    pub struct OpAmpSot23 {
        symbol: "cuprite_basic:OPAMP",
        value: param,
        pins: { "1" => "out", "2" => "vee", "3" => "in_p", "4" => "in_n", "5" => "vcc" },
        sim_model: inline,
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

kicad_part! {
    /// A dual op-amp in SOIC-8 with two of the [`OpAmpSot23`] models; the value is the part number.
    pub struct DualOpAmpSoic8 {
        symbol: "cuprite_basic:OPAMP_DUAL",
        value: param,
        pins: {
            "1" => "out_a", "2" => "in_n_a", "3" => "in_p_a", "4" => "vee",
            "5" => "in_p_b", "6" => "in_n_b", "7" => "out_b", "8" => "vcc",
        },
        sim_model: inline,
        symbol_dir: "libs/symbols",
        footprint_dir: "libs/footprints",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        circuit::CircuitBuilder,
        naming::NetLabel,
        parts::Part,
        spice::{IndependentSource, SpicePartInfo},
    };

    #[test]
    fn test_parts() {
        let parts: Vec<Box<dyn Part>> = vec![
            Box::new(Resistor0603::new("10k")),
            Box::new(Capacitor0603::new("100n")),
            Box::new(Inductor0603::new("10u")),
            Box::new(DiodeSod123::new("1N4148")),
            Box::new(Led0603::new("red")),
            Box::new(OpAmpSot23::new("LMV321")),
            Box::new(DualOpAmpSoic8::new("LM358")),
        ];
        for part in parts {
            let info = part.kicad().unwrap();
            assert!(info.check_pins(&part.pin_ids()).is_empty(), "{part:?}");
            let spice = part.spice().unwrap();
            assert!(
                spice
                    .check(&part.pin_ids(), &part.internal_connections())
                    .is_empty(),
                "{part:?}"
            );
            assert!(matches!(spice, SpicePartInfo::Elements { .. }));
        }
        assert_eq!(DiodeSod123::A, "a");
        assert_eq!(OpAmpSot23::PINS, ["out", "vee", "in_p", "in_n", "vcc"]);
    }

    /// Runs an operating point analysis and returns `v("/OUT")`.
    fn out_voltage(circuit: &CircuitBuilder) -> f64 {
        let deck = circuit
            .build(&())
            .to_netlist()
            .unwrap()
            .to_spice()
            .unwrap()
            .deck()
            .control(["op", r#"let out = v("/OUT")"#, "print out"]);
        let sim = deck.run().unwrap();
        sim.expect_value("out")
    }

    /// Channel B of the dual op-amp as a non-inverting amplifier with a gain of 11.
    #[test]
    fn test_simulate_dual_opamp() {
        let mut circuit = CircuitBuilder::new();
        let amp = circuit.instantiate_part(Box::new(DualOpAmpSoic8::new("LM358")));
        let feedback = circuit.instantiate_part(Box::new(Resistor0603::new("10k")));
        let ground = circuit.instantiate_part(Box::new(Resistor0603::new("1k")));
        circuit.connect(amp["out_b"], feedback["1"]);
        circuit.connect(feedback["2"], amp["in_n_b"]);
        circuit.connect(amp["in_n_b"], ground["1"]);
        circuit.label(ground["2"], NetLabel::global("GND"));
        circuit.label(amp["out_b"], NetLabel::local("OUT"));
        // Channel A follows ground.
        circuit.connect(amp["out_a"], amp["in_n_a"]);
        circuit.label(amp["in_p_a"], NetLabel::global("GND"));
        let input = circuit.instantiate_part(IndependentSource::voltage(0.1));
        circuit.connect(input["p"], amp["in_p_b"]);
        circuit.label(input["n"], NetLabel::global("GND"));
        let supply = circuit.instantiate_part(IndependentSource::voltage(5.0));
        circuit.connect(supply["p"], amp["vcc"]);
        circuit.connect(supply["n"], amp["vee"]);
        circuit.label(supply["n"], NetLabel::global("GND"));
        let out = out_voltage(&circuit);
        assert!((out - 1.1).abs() < 1e-3, "out = {out}");
    }

    /// The forward voltages of the diode and the LED at about 1 mA and 10 mA.
    #[test]
    fn test_simulate_diodes() {
        for (diode, current, range) in [
            (
                Box::new(DiodeSod123::new("D")) as Box<dyn Part>,
                1e-3,
                0.5..0.8,
            ),
            (Box::new(Led0603::new("red")), 10e-3, 1.6..2.2),
        ] {
            let mut circuit = CircuitBuilder::new();
            let d = circuit.instantiate_part(diode);
            let source = circuit.instantiate_part(IndependentSource::current(current));
            // The current flows from p through the source to n, so into the anode.
            circuit.label(source["p"], NetLabel::global("GND"));
            circuit.connect(source["n"], d["a"]);
            circuit.label(d["a"], NetLabel::local("OUT"));
            circuit.label(d["k"], NetLabel::global("GND"));
            let out = out_voltage(&circuit);
            assert!(
                range.contains(&out),
                "forward voltage {out} not in {range:?}"
            );
        }
    }

    /// A circuit with every basic part; its netlists are compared with KiCad's export by
    /// `tools/compare_kicad_cli_netlist.py --library-symbols [--spice] tests/golden/basic_parts.net`.
    #[test]
    fn test_golden() {
        let mut c = CircuitBuilder::new();
        let single = c.instantiate_part_named("single", Box::new(OpAmpSot23::new("LMV321")));
        let dual = c.instantiate_part_named("dual", Box::new(DualOpAmpSoic8::new("LM358")));
        let r = c.instantiate_part_named("r", Box::new(Resistor0603::new("10k")));
        let cap = c.instantiate_part_named("c", Box::new(Capacitor0603::new("100n")));
        let l = c.instantiate_part_named("l", Box::new(Inductor0603::new("10u")));
        let d = c.instantiate_part_named("d", Box::new(DiodeSod123::new("1N4148")));
        let led = c.instantiate_part_named("led", Box::new(Led0603::new("red")));
        let gnd = NetLabel::global("GND");
        let vcc = NetLabel::global("+5V");
        // Single op-amp: a follower of IN driving the LED through R.
        c.label(single["in_p"], NetLabel::local("IN"));
        c.connect(single["out"], single["in_n"]);
        c.connect(single["out"], r["1"]);
        c.connect(r["2"], led["a"]);
        c.label(led["k"], gnd.clone());
        c.label(single["vcc"], vcc.clone());
        c.label(single["vee"], gnd.clone());
        // Dual op-amp: channel A buffers IN through an LC filter, channel B follows ground.
        c.connect(dual["in_p_a"], l["2"]);
        c.label(l["1"], NetLabel::local("IN"));
        c.connect(dual["in_p_a"], cap["1"]);
        c.label(cap["2"], gnd.clone());
        c.connect(dual["out_a"], dual["in_n_a"]);
        c.label(dual["out_a"], NetLabel::local("OUT"));
        c.connect(dual["out_b"], dual["in_n_b"]);
        c.label(dual["in_p_b"], gnd.clone());
        c.label(dual["vcc"], vcc.clone());
        c.label(dual["vee"], gnd.clone());
        // The diode clamps OUT to +5V.
        c.connect(d["a"], dual["out_a"]);
        c.label(d["k"], vcc);
        let netlist = c.build(&()).to_netlist().unwrap();
        let mut out = Vec::new();
        netlist
            .to_kicad()
            .unwrap()
            .with_source("src/basic.rs")
            .write(&mut out)
            .unwrap();
        crate::test_parts::check_golden("basic_parts.net", &String::from_utf8(out).unwrap());
        let spice = netlist.to_spice().unwrap().with_title("basic_parts");
        crate::test_parts::check_golden("basic_parts.cir", &spice.to_string());
    }
}
